INSERT OR IGNORE INTO sc_content (id, author_id, title, content, slug, summary, cover_img, cover_alt, type, status, published_at, created_at, updated_at) VALUES
('20000000-0000-4000-8000-000000000001', '99999999-0000-4000-8000-000000000000', 'Casa conectada: o que vale a pena automatizar primeiro', '<p>Iluminação, câmeras, sensores de presença: nem toda automação entrega o mesmo valor. Veja por onde começar a transformar sua casa em um lar conectado.</p>', 'casa-conectada-o-que-automatizar-primeiro', 'Um guia prático para automatizar sua casa sem desperdício: prioridades, custos e ganhos reais.', '/img/blog-placeholder-1.jpg', 'Casa inteligente à noite com luzes conectadas a uma rede', 'blog', 'published', '2026-07-24T12:00:00Z', datetime('now'), datetime('now')),
('20000000-0000-4000-8000-000000000002', '99999999-0000-4000-8000-000000000000', 'Segurança doméstica: câmeras e sensores que fazem diferença', '<p>Monitorar o que acontece na sua casa mesmo à distância deixou de ser luxo. Conheça as combinações de câmera, sensor e alerta que realmente protegem.</p>', 'seguranca-domestica-cameras-e-sensores', 'Como montar uma rede de segurança residencial eficiente: posicionamento, integração e notificações inteligentes.', '/img/blog-placeholder-2.jpg', 'Câmera de segurança residencial integrada a aplicativo', 'blog', 'published', '2026-07-17T12:00:00Z', datetime('now'), datetime('now')),
('20000000-0000-4000-8000-000000000003', '99999999-0000-4000-8000-000000000000', 'Economia de energia: medindo para reduzir de verdade', '<p>O primeiro passo para gastar menos é medir. Sensores de consumo, rotinas inteligentes e tarifas: o que funciona na prática.</p>', 'economia-de-energia-medindo-para-reduzir', 'Dados reais sobre consumo de energia e as automações que reduzem a conta sem abrir mão de conforto.', '/img/blog-placeholder-3.jpg', 'Painel de consumo de energia de uma casa inteligente', 'blog', 'published', '2026-07-10T12:00:00Z', datetime('now'), datetime('now')),
('20000000-0000-4000-8000-000000000004', '99999999-0000-4000-8000-000000000000', 'Comunidade: vizinhos conectados moram melhor', '<p>Alertas de segurança, entregas e emergências: quando os vizinhos se comunicam pela rede certa, a rua inteira ganha.</p>', 'comunidade-vizinhos-conectados', 'O papel da vizinhança conectada na segurança e na qualidade de vida: casos reais de redes comunitárias.', '/img/blog-placeholder-4.jpg', 'Bairro residencial à noite com casas iluminadas', 'blog', 'published', '2026-07-03T12:00:00Z', datetime('now'), datetime('now')),
('20000000-0000-4000-8000-000000000005', '99999999-0000-4000-8000-000000000000', 'Privacidade no mundo IoT: quem vê o que acontece na sua casa', '<p>Dispositivos conectados coletam dados o tempo todo. Saiba o que cada aparelho enxerga e como proteger sua privacidade.</p>', 'privacidade-no-mundo-iot', 'Guia de privacidade para dispositivos conectados: permissões, criptografia e boas práticas para sua rede doméstica.', '/img/blog-placeholder-5.jpg', 'Rede doméstica protegida com cadeado digital', 'blog', 'published', '2026-06-26T12:00:00Z', datetime('now'), datetime('now')),
('20000000-0000-4000-8000-000000000006', '99999999-0000-4000-8000-000000000000', 'Montando seu painel de controle: o coração da casa inteligente', '<p>Um bom painel reúne câmeras, sensores, consumo e automações em um só lugar. Veja como configurar o seu.</p>', 'montando-seu-painel-de-controle', 'Passo a passo para centralizar o monitoramento da sua casa em um único painel, com os dados certos na ordem certa.', '/img/blog-placeholder-1.jpg', 'Dashboard de controle de automação residencial em tablet', 'blog', 'published', '2026-06-19T12:00:00Z', datetime('now'), datetime('now'));
